  let expected=url.searchParams.get('plmr_engine');
  if(!expected&&request.referrer){try{expected=new URL(request.referrer).searchParams.get('plmr_engine')}catch{/* Non-URL referrers carry no build identity. */}}
  if(expected&&expected!==PLMR_ENGINE_BUILD&&expected!==FACADE_ASSET_VERSION){event.respondWith(fetch(request,{cache:'no-cache'}));return;}
